function renderContact(){
 const email=typeof settings.supportEmail==='string'?settings.supportEmail.trim():'';
 $('contactLink').href=email?'mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent(t('supportSubject')):'#contact';
}
$('contactLink').onclick=event=>{
 if($('contactLink').getAttribute('href').startsWith('mailto:'))return;
 event.preventDefault();text('actionTitle',t('contact'));text('actionBody',t('supportUnavailable'));
 text('actionMessage','');$('resetForm').hidden=true;$('actionConfirm').hidden=true;$('actionDialog').showModal();
};

let feeState=null, feeReceivedAt=0;
function renderFeeNotice(){
 const visible=!!me&&!!feeState&&Number(feeState.pendingAmount)>0;
 $('feeNotice').hidden=!visible;
 if(!visible){$('payFees').disabled=true;return}
 const hold=feeState.hold;
 $('feeNotice').classList.toggle('fee-hold',hold);
 text('feeNoticeTitle',t(hold?'feeHoldTitle':'feeTitle'));
 text('feeNoticeAmount',num(feeState.pendingAmount,6)+' USDC');
 text('feeNoticeBody',t(hold?'feeHoldBody':'feeNoticeBody'));
 const serverNow=feeState.serverTime+(performance.now()-feeReceivedAt);
 const seconds=Math.max(0,Math.ceil((feeState.deadlineAt-serverNow)/1000));
 const hours=Math.floor(seconds/3600),minutes=Math.floor((seconds%3600)/60);
 const remaining=hours+' h '+String(minutes).padStart(2,'0')+' min';
 text('feeNoticeDeadline',hold?'':seconds>0?t('feeDeadline').replace('{date}',stamp(feeState.deadlineAt)).replace('{time}',remaining):t('feeDueNow'));
 $('payFeesNotice').disabled=hold;
 $('payFees').disabled=hold;
}
function clearPrivateState(){
 me=null;feeState=null;renderUser();renderFeeNotice();
 $('tradeRows').replaceChildren();text('username','');text('walletLabel','');text('agentStatus','');
 $('privateNotice').hidden=true;
 for(const id of ['actionDialog','consentDialog'])if($(id).open)$(id).close();
}
setInterval(renderFeeNotice,30000);

for(const [language,label] of Object.entries({en:'View real account log',es:'Ver registro de la cuenta real',fr:'Voir le journal du compte réel',de:'Protokoll des echten Kontos öffnen'}))dictionaries[language].audit=label;

let lang=localStorage.getItem('cryptoloveLanguage')||'en',me=null,settings={},history=null,filtered=[],position=0,playing=false,timer=null,signupMode=false,live=null,backtest=null,backtestMessageKey=null;
if(!dictionaries[lang])lang='en';
const t=k=>dictionaries[lang][k]??dictionaries.en[k]??k;
const num=(n,d=2)=>Number(n).toLocaleString('de-DE',{maximumFractionDigits:d,minimumFractionDigits:d});
const stamp=x=>CryptoLoveBacktest.stamp(x);
const pair=x=>CryptoLoveBacktest.pair(x);
const text=(id,value)=>{$(id).textContent=value};
function applyLanguage(){document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));document.querySelectorAll('.flag').forEach(el=>{el.classList.toggle('selected',el.dataset.lang===lang);el.setAttribute('aria-pressed',String(el.dataset.lang===lang))});setMode(signupMode);renderContact();renderUser();renderLive();renderFeeNotice();if(backtest){renderReplay();renderHistory();renderBacktestMessage()}if(settings.feeBasis==='margin'){text('feeExplanation',t('feeMargin'));document.querySelector('[data-i18n="consentFee"]').textContent=t('feeMargin')}}
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;localStorage.setItem('cryptoloveLanguage',lang);applyLanguage();if(me)loadTrades()});
function toast(s){text('toast',s);$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,6500)}
function authFeedback(message,kind='info'){text('authMessage',message);$('authMessage').className='form-message '+kind}
function actionFeedback(message,kind='error'){text('actionMessage',message);$('actionMessage').className='form-message '+kind}
function showError(err){const message=err.code===4001?'MetaMask: '+(lang==='es'?'firma cancelada':'signature cancelled'):err.message||t('error');if($('authDialog').open)authFeedback(message,'error');else if($('actionDialog').open)actionFeedback(message);else if($('consentDialog').open){text('consentMessage',message);$('consentMessage').className='form-message error'}else toast(message)}
function action(fn){return async function(e){e?.preventDefault?.();const btn=e?.currentTarget;try{if(btn?.tagName==='BUTTON')btn.disabled=true;await fn(e)}catch(err){showError(err)}finally{if(btn?.tagName==='BUTTON')btn.disabled=false}}}
const apiBase=()=>{const url=window.CRYPTOLOVE?.apiUrl||'';if(!url.startsWith('https://')||url.includes('.example'))throw Error(t('apiMissing'));return url.replace(/\/$/,'')};
function apiError(data,status){
 const detail=data?.detail;
 const translations={'Email service is not configured. Contact the operator.':'mailUnavailable','Invalid sign-in details.':'invalidLogin','Confirm your email first.':'unverifiedEmail','Email already registered.':'emailRegistered','Origin not allowed':'serverError','Sign in to continue.':'sessionExpired','Finish open trades and their reconciliation before changing wallet.':'walletBusy','Close positions and cancel open orders on the current wallet before changing it.':'walletOrders','A payment is awaiting reconciliation. Resolve it before changing wallet.':'walletUncertain','Could not verify the current wallet. No wallet was changed. Try again later.':'walletCheckFailed','Wallet already linked to another profile.':'walletTaken'};
 if(typeof detail==='string')return translations[detail]?t(translations[detail]):detail;
 if(Array.isArray(detail)){if(detail.some(e=>e.loc?.includes('email')))return t('invalidEmail');if(detail.some(e=>e.loc?.includes('password')))return t('shortPassword')}
 return t(status>=500?'serverError':'error');
}
async function api(path,body){
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),body===undefined?15000:60000);
 try{
  let res;try{res=await fetch(apiBase()+path,{method:body===undefined?'GET':'POST',credentials:'include',signal:controller.signal,headers:body===undefined?{}:{'Content-Type':'application/json','X-CryptoLove':'1'},body:body===undefined?undefined:JSON.stringify(body)})}catch(err){throw Error(t(err.name==='AbortError'?'requestTimeout':'apiUnavailable'))}
  let data;try{data=await res.json()}catch{throw Error(t(res.status>=500?'apiUnavailable':'serverError'))}
  if(!res.ok){if(res.status===401&&me){clearPrivateState();toast(t('sessionExpired'))}throw Error(apiError(data,res.status))}return data;
 }finally{clearTimeout(timeout)}
}
let authBusy=false;
async function authAction(fn){
 if(authBusy)return;authBusy=true;$('authForm').setAttribute('aria-busy','true');
 for(const id of ['authSubmit','forgot','resend','loginTab','signupTab'])$(id).disabled=true;
 authFeedback(t('working'));
 try{await fn()}catch(err){authFeedback(err.message||t('error'),'error')}
 finally{authBusy=false;$('authForm').removeAttribute('aria-busy');for(const id of ['authSubmit','forgot','resend','loginTab','signupTab'])$(id).disabled=false}
}
function setMode(mode){signupMode=mode;text('authTitle',t(mode?'join':'welcome'));text('authSubmit',t(mode?'signUp':'signIn'));$('signupTab').classList.toggle('selected',mode);$('loginTab').classList.toggle('selected',!mode);$('passwordHint').hidden=!mode;$('authForm').elements.password.minLength=mode?12:1;$('authForm').elements.password.autocomplete=mode?'new-password':'current-password'}
$('loginTab').onclick=()=>{setMode(false);authFeedback('')};$('signupTab').onclick=()=>{setMode(true);authFeedback('')};
$('authButton').onclick=()=>{$('authMessage').textContent='';$('authDialog').showModal()};
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
async function refreshMe(){me=await api('/me');renderUser();try{await loadTrades()}catch(err){if(me){$('privateNotice').hidden=false;text('privateNotice',err.message)}else throw err}}
function renderUser(){const logged=!!me&&!!me.verified;$('connectButton').hidden=!logged;$('walletActions').hidden=!logged;text('connectLabel',t(me?.wallet?'changeWallet':'connect'));$('authButton').hidden=logged;$('privateButton').hidden=!logged;$('private').hidden=!logged;if(!logged)return;text('username',me.email);text('walletLabel',me.wallet||t('unlinked'));text('agentStatus',(me.agent_address?(me.active?t('active'):t('paused')):t(me.wallet?'needsAuthorization':'unlinked'))+(settings.tradingEnabled?'':' · '+t('globalPause')));$('authorizeButton').hidden=!!me.agent_address;$('pauseButton').hidden=!me.agent_address;text('pauseButton',t(me.active?'pause':'resume'));$('privateNotice').hidden=!me.last_error;if(me.last_error)text('privateNotice',me.last_error)}
$('privateButton').onclick=()=>$('private').scrollIntoView({behavior:'smooth'});
$('authForm').onsubmit=event=>{event.preventDefault();return authAction(async()=>{
 const form=$('authForm'),data=Object.fromEntries(new FormData(form));
 if(signupMode){const result=await api('/auth/signup',data);setMode(false);form.elements.password.value='';authFeedback(t(result.delivery==='queued'?'mailDelayed':'checkEmail'),result.delivery==='queued'?'warning':'success')}
 else{await api('/auth/login',data);await refreshMe();form.reset();$('authDialog').close();$('private').scrollIntoView({behavior:'smooth'})}
})};
for(const [id,path]of[['forgot','/auth/forgot'],['resend','/auth/resend']])$(id).onclick=()=>{
 const email=$('authForm').elements.email;if(!email.reportValidity()){authFeedback(t('invalidEmail'),'error');return}
 return authAction(async()=>{await api(path,{email:email.value});authFeedback(t(id==='forgot'?'forgotSent':'resendSent'),'success')});
};
$('logout').onclick=action(async()=>{await api('/auth/logout',{});clearPrivateState();window.scrollTo({top:0,behavior:'smooth'})});

const announced=[];window.addEventListener('eip6963:announceProvider',event=>{if(event.detail?.info?.rdns==='io.metamask')announced.push(event.detail.provider)});window.dispatchEvent(new Event('eip6963:requestProvider'));
async function metamask(select=false){let provider=announced[0];if(!provider){window.dispatchEvent(new Event('eip6963:requestProvider'));await new Promise(r=>setTimeout(r,250));provider=announced[0]}if(!provider){const candidates=window.ethereum?.providers||[window.ethereum];provider=candidates.find(p=>p?.isMetaMask&&!p?.isBraveWallet&&!p?.isCoinbaseWallet)}if(!provider)throw Error(t('noWallet'));if(select){try{await provider.request({method:'wallet_requestPermissions',params:[{eth_accounts:{}}]})}catch(err){if(![-32601,4200].includes(err.code))throw err}}const accounts=await provider.request({method:'eth_requestAccounts'});if(!accounts?.[0])throw Error(t('noWallet'));return{provider,address:accounts[0]}}
async function connectWallet(select=false){if(!me?.verified){$('authDialog').showModal();return false}const{provider,address}=await metamask(select);const challenge=await api('/wallet/challenge',{address});const signature=await provider.request({method:'personal_sign',params:['0x'+Array.from(new TextEncoder().encode(challenge.message)).map(b=>b.toString(16).padStart(2,'0')).join(''),address]});const linked=await api('/wallet/link',{id:challenge.id,signature});await refreshMe();toast(t(linked.changed?'walletChanged':'connected'));return true}
$('connectButton').onclick=action(async()=>{if(await connectWallet(!!me?.wallet)){$('private').scrollIntoView({behavior:'smooth'});if(!me.agent_address)openConsent()}});
function openConsent(){text('consentMessage','');$('acceptConsent').checked=false;text('consentNetwork',t('network')+': Hyperliquid '+(settings.network||'testnet').toUpperCase());$('consentDialog').showModal()}
$('authorizeButton').onclick=action(async()=>{if(!me.wallet&&!await connectWallet())return;openConsent()});
async function signedRequest(prepare,commit){const{provider,address}=await metamask();if(address.toLowerCase()!==me.wallet)throw Error(t('differentWallet'));const chain=await provider.request({method:'eth_chainId'});const prepared=await api(prepare,{chain_id:chain,consent:true});return{provider,address,prepared,commit}}
async function signPrepared(x){const accounts=await x.provider.request({method:'eth_accounts'});if(accounts[0]?.toLowerCase()!==x.address.toLowerCase())throw Error(t('differentWallet'));const signature=await x.provider.request({method:'eth_signTypedData_v4',params:[x.address,JSON.stringify(x.prepared.typedData)]});return api(x.commit,{id:x.prepared.id,signature})}
$('signAgent').onclick=action(async()=>{if(!$('acceptConsent').checked)throw Error(t('agree'));const x=await signedRequest('/wallet/prepare','/wallet/authorize');await signPrepared(x);$('consentDialog').close();await refreshMe();toast(t('accepted'))});
$('pauseButton').onclick=action(async()=>{await api('/subscription',{active:!me.active});await refreshMe()});
function confirmDialog(title,body,label,fn){actionFeedback('');text('actionTitle',title);text('actionBody',body);$('resetForm').hidden=true;$('actionConfirm').hidden=false;text('actionConfirm',label);$('actionConfirm').onclick=action(async()=>{await fn();$('actionDialog').close()});$('actionDialog').showModal()}
$('payFees').onclick=action(async()=>{const x=await signedRequest('/fees/prepare','/fees/pay');confirmDialog(t('confirmPayment'),t('paymentText').replace('{amount}',num(x.prepared.amount,6)).replace('{wallet}',x.prepared.destination),t('confirmPayment'),async()=>{await signPrepared(x);toast(t('paid'));await loadTrades()})});
$('payFeesNotice').onclick=()=>$('payFees').click();
$('deleteAccount').onclick=()=>confirmDialog(t('delete'),t('deleteBody'),t('delete'),async()=>{await api('/account/delete',{});clearPrivateState();toast(t('deleteDone'))});
function td(value,small){const el=document.createElement('td');el.textContent=value;if(small){const s=document.createElement('small');s.textContent=small;el.append(s)}return el}
async function loadTrades(){if(!me)return;const uid=me.id;const data=await api('/trades');if(!me||me.id!==uid)return;feeState=data.fees;feeReceivedAt=performance.now();renderFeeNotice();$('tradeRows').replaceChildren();$('emptyTrades').hidden=!!data.trades.length;for(const row of data.trades){const tr=document.createElement('tr');tr.append(td(pair(row.coin),row.side),td(stamp(row.opened)),td(row.closed?stamp(row.closed):t(row.status==='reconciling'?'reconciling':'open')),td(num(row.entry,6)),td(row.exit?num(row.exit,6):'—'));const profit=td(row.return_pct!==null?num(row.return_pct)+'%':'—');profit.classList.toggle('negative',Number(row.return_pct)<0);tr.append(profit,td(num(row.fee,6),t(row.fee_status==='paid'?'feePaid':row.fee_status==='pending'?'feePending':'feeNone')),td(row.balance?num(row.balance):'—',row.balance_at?stamp(row.balance_at):''));$('tradeRows').append(tr)}$('privateNotice').hidden=!me.last_error;if(me.last_error)text('privateNotice',me.last_error);if(data.invoices.length){$('privateNotice').hidden=false;text('privateNotice',lang==='es'?'Hay un pago sin confirmar. No lo repitas; consulta con el operador.':'A payment is awaiting reconciliation. Do not repeat it; contact the operator.')}}

async function initGoogle(){if(!settings.googleClientId)return;const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=()=>{google.accounts.id.initialize({client_id:settings.googleClientId,callback:action(async response=>{const result=await api('/auth/google',{credential:response.credential});if(result.needsConfirmation){authFeedback(t(result.delivery==='queued'?'mailDelayed':'checkEmail'),result.delivery==='queued'?'warning':'success');return}me=result;$('authDialog').close();await refreshMe();$('private').scrollIntoView({behavior:'smooth'})})});$('googleWrap').hidden=false;google.accounts.id.renderButton($('googleButton'),{type:'standard',theme:'outline',size:'large',width:300})};document.head.append(script)}
async function handleLink(){
 const match=location.hash.slice(1).match(/^(verify|reset|unsubscribe)=(.+)$/);if(!match)return;
 const kind=match[1],token=decodeURIComponent(match[2]);
 const clean=()=>window.history.replaceState(null,'',location.pathname);
 if(kind==='verify'){
  setMode(false);$('authDialog').showModal();authFeedback(t('verifyWorking'));
  try{await api('/auth/verify',{token});clean();authFeedback(t('verifyDone'),'success')}catch(err){authFeedback(err.message,'error')}
 }else if(kind==='unsubscribe'){
  clean();confirmDialog(t('delete'),t('deleteBody'),t('delete'),async()=>{await api('/auth/unsubscribe',{token});clearPrivateState();toast(t('deleteDone'))});
 }else{
  clean();text('actionTitle',t('newPassword'));text('actionBody','');actionFeedback('');$('actionConfirm').hidden=true;$('resetForm').hidden=false;
  $('resetForm').onsubmit=action(async()=>{
   const button=$('resetForm').querySelector('button');button.disabled=true;actionFeedback(t('working'),'info');
   try{await api('/auth/reset',{token,password:$('resetForm').elements.password.value});$('resetForm').reset();$('actionDialog').close();setMode(false);$('authDialog').showModal();authFeedback(t('savedPassword'),'success')}finally{button.disabled=false}
  });$('actionDialog').showModal();
 }
}

function renderLive(){
 const valid=live?.returnPct!==null&&live?.returnPct!==undefined&&Number.isFinite(Number(live.returnPct));
 const percent=valid?Number(live.returnPct):null;
 $('liveReturn').replaceChildren(document.createTextNode(valid?(percent>0?'+':'')+num(percent):'—'),Object.assign(document.createElement('span'),{textContent:'%'}));
 $('liveReturn').classList.toggle('negative',valid&&percent<0);
 if(valid){
  const status=live.status==='no_trades'?t('noTrades'):'';
  text('liveStatus',(live.stale?t('stale')+' ':'')+status);
  $('liveStatus').title=live.asOf?t('updated')+': '+stamp(live.asOf)+' UTC':'';
 }else{
  $('liveStatus').removeAttribute('title');
  const connected=['insufficient_baseline','awaiting_next_sample'].includes(live?.status);
  text('liveStatus',t(connected?'baselineMissing':!live||live.status==='unconfigured'?'awaiting':'noData'));
 }
 $('liveStatus').hidden=!$('liveStatus').textContent.trim();
 $('auditLink').hidden=false;$('auditLink').href='account-log.html?lang='+encodeURIComponent(lang);
}
async function loadLive(){try{live=await api('/public/performance');renderLive()}catch{if(live)live.stale=true;else live={status:'unavailable',returnPct:null};renderLive()}}
function renderBacktestMessage(){
 const message=$('backtestMessage');
 const pieces=[];
 if(backtestMessageKey)pieces.push(t(backtestMessageKey));
 else if(backtest){if(backtest.partial)pieces.push(t('partialHistory'));if(!filtered.length)pieces.push(t('noSelectedTrades'))}
 message.hidden=!pieces.length;message.textContent=pieces.join(' ');
 message.classList.toggle('error',!!backtestMessageKey&&backtestMessageKey!=='updatedInputs');
}
function datesAfterHistory(){return ['startDate','endDate'].filter(id=>CryptoLoveBacktest.parseDate($(id).value)>CryptoLoveBacktest.MAX_DATE)}
function selectHistory(){
 if(!history)return;
 for(const id of ['startDate','endDate','initialCapital'])$(id).removeAttribute('aria-invalid');
 try{
  const next=CryptoLoveBacktest.replay(history,{start:$('startDate').value,end:$('endDate').value,capital:$('initialCapital').value});
  stop();backtest=next;$('initialCapital').value=num(next.initial);filtered=next.trades;position=filtered.length;backtestMessageKey=null;
  for(const id of ['startDate','endDate','initialCapital'])$(id).removeAttribute('aria-invalid');
  $('timeline').max=filtered.length;$('play').disabled=!filtered.length;$('timeline').disabled=!filtered.length;
  renderHistory();renderReplay();renderBacktestMessage();
 }catch(e){
  stop();backtestMessageKey=e.message;
  const invalid=e.message==='maxDate'?datesAfterHistory():[e.message==='minCapital'||e.message==='amountTooLarge'?'initialCapital':e.message==='dateOrder'?'endDate':'startDate'];
  for(const id of invalid)$(id).setAttribute('aria-invalid','true');renderBacktestMessage();$(invalid[0]).focus();
 }
}
function renderHistory(){
 if(!backtest)return;
 $('historyRows').replaceChildren();
 for(const r of filtered){
  const tr=document.createElement('tr');tr.append(td(pair(r.coin),r.side),td(stamp(r.open)),td(stamp(r.close)));
  for(const value of [r.priceReturnPct,r.cumulativePct]){const cell=td((value>0?'+':'')+num(value)+'%');cell.classList.toggle('negative',value<0);tr.append(cell)}
  tr.append(td(num(r.simulatedBalance)));$('historyRows').append(tr);
 }
 text('sourceInfo',filtered.length+' '+t('trades')+' · '+CryptoLoveBacktest.date(backtest.from)+' → '+CryptoLoveBacktest.date(backtest.to-1)+' · '+t('initialCapital')+': '+num(backtest.initial)+' USDC');
}
const svgNode=(tag,attrs,content)=>{const el=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);if(content!==undefined)el.textContent=content;return el};
function values(){return backtest?.balances||[1000]}
function renderReplay(){if(!backtest)return;$('chartEmpty').hidden=filtered.length>0;text('chartEmpty',t('noSelectedTrades'));const data=values();const current=data[position];text('indexValue',num(current));const totalPct=(current/backtest.initial-1)*100;text('indexReturn',(totalPct>0?'+':'')+num(totalPct)+'%');$('indexReturn').classList.toggle('negative',totalPct<0);text('progress',position+' / '+filtered.length);$('timeline').value=position;const r=filtered[Math.max(0,position-1)];text('replayCoin',position&&r?pair(r.coin):'—');text('replayOpen',position&&r?stamp(r.open):'—');text('replayClose',position&&r?stamp(r.close):'—');text('replayProfit',position&&r?(r.priceReturnPct>=0?'+':'')+num(r.priceReturnPct)+'%':'—');$('replayProfit').classList.toggle('negative',position>0&&r?.priceReturnPct<0);
const log=$('scale').value==='log',transform=v=>log?Math.log10(Math.max(.01,v)):v,extent=data.map(transform),lo=Math.min(...extent),hi=Math.max(...extent),pad=Math.max((hi-lo)*.09,log?.1:1),min=lo-pad,max=hi+pad;const X=i=>94+i/Math.max(1,filtered.length)*882,Y=v=>275-(transform(v)-min)/(max-min)*235;const pts=data.slice(0,position+1).map((v,i)=>[X(i),Y(v)]);const path=pts.map(([x,y],i)=>(i?'L':'M')+x.toFixed(2)+','+y.toFixed(2)).join(' ');$('curve').setAttribute('d',path);$('area').setAttribute('d',path+` L${X(position)},275 L94,275 Z`);$('cursorDot').setAttribute('cx',X(position));$('cursorDot').setAttribute('cy',Y(current));$('grid').replaceChildren();for(let i=0;i<5;i++){const v=min+(max-min)*i/4,y=275-i/4*235,label=log?10**v:v;$('grid').append(svgNode('line',{x1:94,y1:y,x2:976,y2:y,stroke:'#e8eef8','stroke-dasharray':'3 5'}),svgNode('text',{x:83,y:y+4,'text-anchor':'end',fill:'#8298bc','font-size':'10'},num(label,Math.abs(label)<1?2:0)))}for(let i=0;i<3;i++){const n=Math.round(filtered.length*i/2),row=filtered[Math.max(0,n-1)];if(row)$('grid').append(svgNode('text',{x:X(n),y:307,'text-anchor':i===0?'start':i===2?'end':'middle',fill:'#8298bc','font-size':'10'},CryptoLoveBacktest.date(row.close)))} }
function stop(){playing=false;clearTimeout(timer);text('play','▶');$('play').setAttribute('aria-label',lang==='es'?'Reproducir':'Play')}
function tick(){if(!playing)return;if(position>=filtered.length){stop();return}position++;renderReplay();timer=setTimeout(tick,650/Number($('speed').value))}
$('play').onclick=()=>{if(!history||!filtered.length)return;if(playing){stop();return}if(position>=filtered.length)position=0;playing=true;text('play','Ⅱ');$('play').setAttribute('aria-label',lang==='es'?'Pausar':'Pause');tick()};$('restart').onclick=()=>{stop();position=0;renderReplay()};$('timeline').oninput=()=>{stop();position=Number($('timeline').value);renderReplay()};$('scale').onchange=renderReplay;$('backtestForm').onsubmit=event=>{event.preventDefault();selectHistory()};
for(const id of ['startDate','endDate','initialCapital'])$(id).addEventListener('input',()=>{
 stop();const invalid=datesAfterHistory();backtestMessageKey=invalid.length?'maxDate':'updatedInputs';
 for(const field of ['startDate','endDate']){if(invalid.includes(field))$(field).setAttribute('aria-invalid','true');else $(field).removeAttribute('aria-invalid')}
 renderBacktestMessage();
});
$('chart').addEventListener('click',event=>{if(!backtest)return;const rect=$('chart').getBoundingClientRect();position=Math.max(0,Math.min(filtered.length,Math.round(((event.clientX-rect.left)/rect.width*1000-94)/882*filtered.length)));stop();renderReplay()});
async function init(){
 applyLanguage();
 try{const r=await fetch('history.json');if(!r.ok)throw Error('history');history=await r.json();$('startDate').value=CryptoLoveBacktest.date(CryptoLoveBacktest.MIN_DATE);$('endDate').value=CryptoLoveBacktest.date(history.period.to);selectHistory()}catch{text('chartEmpty',lang==='es'?'No se pudo cargar history.json':'Could not load history.json')}
 const accountReady=(async()=>{try{settings=await api('/public/config');applyLanguage();await initGoogle()}catch{}try{await refreshMe()}catch{me=null;renderUser()}})();
 await Promise.all([accountReady,handleLink(),loadLive()]);
 setInterval(()=>{loadLive();if(me)loadTrades().catch(()=>{})},60000);
}init();
